function getaesdata(iv,data){
var config = {
iv:iv,
bm: "UTF-8",
dataPassword:"hotmanga.aes.key"
}
var list = JSON.parse(decrypt(config, hexStringToBase64(data)));
return list;
}

function hexStringToBase64(hexstring) {
    return btoa(hexstring.match(/\w{2}/g).map(function(a) {
        return String.fromCharCode(parseInt(a, 16));
    }).join(""));
}

